
(()=>{'use strict';const S={users:[],config:null,holidays:[],holidayMap:new Map(),schedule:{},date:new Date(),admin:false,lastReport:[]};const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const parseISO=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)};const dow=s=>{const d=parseISO(s).getDay();return d===0?7:d};const monthStart=(y,m)=>{const f=new Date(y,m,1),o=(f.getDay()+6)%7;return new Date(y,m,1-o)};async function sha256(t){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}function range(a,b){const out=[];for(let d=parseISO(a);d<=parseISO(b);d.setDate(d.getDate()+1))out.push(iso(d));return out}function isWorkday(day){return S.config.rules.workdays.includes(dow(day))}function hType(day){return S.holidayMap.get(day)?.type||'standard'}function cov(day){return S.config.rules.coverageByDayType[hType(day)]||S.config.rules.coverageByDayType.standard}function unavUser(u,day){return (u.timeOff||[]).some(x=>x.type==='vacation'&&day>=x.start&&day<=x.end)}function name(id){return S.users.find(u=>u.id===id)?.name||id}function role(id){return S.users.find(u=>u.id===id)?.role||'standard'}function unav(id,day){const u=S.users.find(x=>x.id===id);return u?unavUser(u,day):false}function vacDays(u){let n=0;(u.timeOff||[]).filter(x=>x.type==='vacation').forEach(x=>range(x.start,x.end).forEach(d=>{if(isWorkday(d)&&!S.holidayMap.has(d))n++}));return n}function dl(name,obj){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}function dlt(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}async function loadJson(n){const r=await fetch(`data/${n}.json`,{cache:'no-store'});if(!r.ok)throw new Error(`No carga data/${n}.json (${r.status})`);return r.json()}async function load(){const [users,config,shifts,holidays,schedule]=await Promise.all(['users','config','shifts','holidays','schedule'].map(loadJson));Object.assign(S,{users,config,holidays,schedule,holidayMap:new Map(holidays.map(h=>[h.date,h]))})}function evalDay(day){const issues=[];if(!isWorkday(day))return{issues};const c=cov(day),sc=S.schedule[day]||{morning:[],evening:[]},t=hType(day);if(t==='global_closed'){if((sc.morning||[]).length||(sc.evening||[]).length)issues.push({date:day,message:'Cierre global con turnos asignados'});return{issues}}const m=(sc.morning||[]).filter(id=>!unav(id,day)),e=(sc.evening||[]).filter(id=>!unav(id,day));if(m.length<c.morning)issues.push({date:day,message:`Mañana sin cobertura: ${m.length}/${c.morning}`});if(e.length<c.evening)issues.push({date:day,message:`Tarde sin cobertura: ${e.length}/${c.evening}`});const both=m.filter(id=>e.includes(id));if(both.length)issues.push({date:day,message:`En ambos turnos: ${both.map(name).join(', ')}`});const se=e.filter(id=>role(id)==='senior').length,st=e.filter(id=>role(id)!=='senior').length;if(c.evening===2&&e.length>0&&(se!==1||st!==1))issues.push({date:day,message:'Tarde debe tener 1 senior + 1 estándar'});[...(sc.morning||[]),...(sc.evening||[])].forEach(id=>{if(unav(id,day))issues.push({date:day,message:`${name(id)} está de vacaciones y asignado`})});return{issues}}function evalMonth(y,m){let issues=[];for(let d=new Date(y,m,1);d.getMonth()===m;d.setDate(d.getDate()+1))issues=issues.concat(evalDay(iso(d)).issues);return{issues}}function report(y,m){const rows=S.users.map(u=>({id:u.id,name:u.name,morningHours:0,eveningHours:0,holidayHours:0,nationalHours:0,regionalHours:0,localHours:0,totalHours:0})),map=new Map(rows.map(r=>[r.id,r]));for(let d=new Date(y,m,1);d.getMonth()===m;d.setDate(d.getDate()+1)){const day=iso(d),t=hType(day),sc=S.schedule[day]||{morning:[],evening:[]};if(!isWorkday(day))continue;for(const id of(sc.morning||[])){const r=map.get(id);if(!r)continue;r.morningHours+=9;r.totalHours+=9;if(t!=='standard'){r.holidayHours+=9;if(t==='national')r.nationalHours+=9;if(t==='regional')r.regionalHours+=9;if(t==='local')r.localHours+=9}}for(const id of(sc.evening||[])){const r=map.get(id);if(!r)continue;r.eveningHours+=9;r.totalHours+=9;if(t!=='standard'){r.holidayHours+=9;if(t==='national')r.nationalHours+=9;if(t==='regional')r.regionalHours+=9;if(t==='local')r.localHours+=9}}}return rows}function gen(y,m,overwrite){let schedule=structuredClone(S.schedule||{}),last=new Set();for(let d=new Date(y,m,1);d.getMonth()===m;d.setDate(d.getDate()+1)){const day=iso(d);if(!isWorkday(day))continue;if(!overwrite&&schedule[day]&&((schedule[day].morning||[]).length||(schedule[day].evening||[]).length))continue;const c=cov(day),t=hType(day);if(t==='global_closed'){schedule[day]={morning:[],evening:[]};continue}const avail=S.users.filter(u=>!unavUser(u,day)),rep=report(y,m);const score=(id,kind)=>{const r=rep.find(x=>x.id===id)||{};let s=0;if(kind==='holiday')s+=(r.holidayHours||0)*10;if(kind==='evening')s+=(r.eveningHours||0)*5;if(last.has(id))s+=20;return s};const seniors=avail.filter(u=>u.role==='senior').sort((a,b)=>score(a.id,'evening')-score(b.id,'evening')),std=avail.filter(u=>u.role!=='senior').sort((a,b)=>score(a.id,'evening')-score(b.id,'evening'));let evening=[];if(c.evening>=2&&seniors.length&&std.length)evening=[seniors[0].id,std[0].id];else evening=avail.sort((a,b)=>score(a.id,'evening')-score(b.id,'evening')).slice(0,c.evening).map(u=>u.id);last=new Set(evening);let rest=avail.filter(u=>!evening.includes(u.id));rest.sort((a,b)=>score(a.id,t==='standard'?'morning':'holiday')-score(b.id,t==='standard'?'morning':'holiday'));schedule[day]={morning:rest.slice(0,c.morning).map(u=>u.id),evening}}S.schedule=schedule}function render(){if(!S.config)return;$('#appName').textContent=S.config.appName;$('#modeBox').textContent=S.admin?'Modo administrador':'Modo lectura';$('#modeBox').className='mode '+(S.admin?'admin':'readonly');$$('.adminOnly').forEach(x=>x.classList.toggle('hidden',!S.admin));$('#btnUnlock').classList.toggle('hidden',S.admin);$('#teamList').innerHTML=S.users.map(u=>`<div class="person"><span>${u.name}</span><span class="pill">${Math.max(0,(u.vacation?.total||0)-vacDays(u))}d</span></div>`).join('');const c=S.config.colors;$('#legend').innerHTML=`<div class="legendItem"><span class="swatch" style="background:${c.global_closed}"></span>Cierre global</div><div class="legendItem"><span class="swatch" style="background:${c.national}"></span>Festivo nacional</div><div class="legendItem"><span class="swatch" style="background:${c.regional}"></span>Festivo Comunidad Valenciana</div><div class="legendItem"><span class="swatch" style="background:${c.local}"></span>Festivo local Alicante</div>`;const r=S.config.rules.coverageByDayType;$('#rulesList').innerHTML=`<li>Normal ${r.standard.morning}/${r.standard.evening}</li><li>Nacional ${r.national.morning}/${r.national.evening}</li><li>Autonómico/local ${r.regional.morning}/${r.regional.evening}</li><li>Cierre global 0/0</li>`;renderCal();const ev=evalMonth(S.date.getFullYear(),S.date.getMonth());$('#qualityBox').textContent=ev.issues.length?`${ev.issues.length} incidencias`:'Sin incidencias';$('#alerts').innerHTML=ev.issues.slice(0,10).map(i=>`<div class="alert"><b>${i.date}</b> - ${i.message}</div>`).join('')}function renderCal(){const y=S.date.getFullYear(),m=S.date.getMonth();$('#monthTitle').textContent=new Date(y,m,1).toLocaleDateString('es-ES',{month:'long',year:'numeric'}).toUpperCase();const cal=$('#calendar');cal.innerHTML='';['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].forEach(d=>cal.insertAdjacentHTML('beforeend',`<div class="dow">${d}</div>`));const start=monthStart(y,m);for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const day=iso(d),sc=S.schedule[day]||{morning:[],evening:[]},hol=S.holidayMap.get(day),ev=evalDay(day);const div=document.createElement('div');div.className=`day ${d.getMonth()!==m?'out ':''}${hType(day)} ${ev.issues.length?'issue':''}`;div.innerHTML=`${ev.issues.length?'<span class="issueDot">!</span>':''}<div class="daynum">${d.getDate()}</div>${hol?`<div class="holiday">${hol.name}</div>`:''}${line('morning',sc.morning)}${line('evening',sc.evening)}`;div.onclick=()=>openDay(day);cal.appendChild(div)}}function line(k,ids=[]){return ids.length?`<div class="shift ${k==='evening'?'evening':''}">${k==='morning'?'M':'T'} | ${ids.map(name).join(', ')}</div>`:''}function openDay(day){$('#dayTitle').textContent=day;$('#dayMeta').textContent=`Cobertura objetivo: ${cov(day).morning} mañana / ${cov(day).evening} tarde`;$('#dayWarnings').innerHTML=evalDay(day).issues.map(i=>`<div class="warn">${i.message}</div>`).join('');const sc=S.schedule[day]||{morning:[],evening:[]};fill('#morningChecks',sc.morning);fill('#eveningChecks',sc.evening);$('#saveDay').onclick=e=>{e.preventDefault();if(!S.admin)return;S.schedule[day]={morning:sel('#morningChecks'),evening:sel('#eveningChecks')};$('#dayDialog').close();render()};$('#dayDialog').showModal()}function fill(q,ids){$(q).innerHTML=S.users.map(u=>`<label class="check"><input type="checkbox" value="${u.id}" ${ids.includes(u.id)?'checked':''} ${!S.admin?'disabled':''}>${u.name}</label>`).join('')}function sel(q){return Array.from(document.querySelectorAll(q+' input:checked')).map(x=>x.value)}function openVac(){ $('#vacUser').innerHTML=S.users.map(u=>`<option value="${u.id}">${u.name}</option>`).join(''); renderVac(); $('#vacDialog').showModal()}function renderVac(){$('#vacList').innerHTML=S.users.map(u=>`<h4>${u.name}</h4>${(u.timeOff||[]).map((v,i)=>`<div class="person"><span>${v.start} → ${v.end}</span><button type="button" data-u="${u.id}" data-i="${i}" class="delVac">Borrar</button></div>`).join('')||'<p>Sin vacaciones</p>'}`).join('');$$('.delVac').forEach(b=>b.onclick=()=>{S.users.find(u=>u.id===b.dataset.u).timeOff.splice(Number(b.dataset.i),1);renderVac();render()})}function bind(){$('#prev').onclick=()=>{S.date.setMonth(S.date.getMonth()-1);render()};$('#next').onclick=()=>{S.date.setMonth(S.date.getMonth()+1);render()};$('#today').onclick=()=>{S.date=new Date();render()};$('#btnUnlock').onclick=()=>$('#adminDialog').showModal();$('#btnLock').onclick=()=>{S.admin=false;render()};$('#doUnlock').onclick=async e=>{e.preventDefault();if(S.config.adminPasswordHash==='REPLACE_WITH_SHA256_HASH')return alert('Configura adminPasswordHash en data/config.json');if(await sha256($('#adminPassword').value)===S.config.adminPasswordHash){S.admin=true;$('#adminDialog').close();render()}else alert('Contraseña incorrecta')};$('#btnVacations').onclick=openVac;$('#addVacation').onclick=e=>{e.preventDefault();const u=S.users.find(x=>x.id===$('#vacUser').value),a=$('#vacFrom').value,b=$('#vacTo').value;if(!u||!a||!b||b<a)return alert('Revisa el rango.');u.timeOff=u.timeOff||[];u.timeOff.push({type:'vacation',start:a,end:b,notes:$('#vacNotes').value||''});renderVac();render()};$('#btnAuto').onclick=()=>$('#autoDialog').showModal();$('#openVacFromAuto').onclick=e=>{e.preventDefault();$('#autoDialog').close();openVac()};$('#runAuto').onclick=e=>{e.preventDefault();gen(S.date.getFullYear(),S.date.getMonth(),$('#overwriteMonth').checked);$('#autoDialog').close();render()};$('#btnBulk').onclick=()=>{$('#bulkUsers').innerHTML=S.users.map(u=>`<option value="${u.id}">${u.name}</option>`).join('');$('#bulkDialog').showModal()};$('#runBulk').onclick=e=>{e.preventDefault();const ids=Array.from($('#bulkUsers').selectedOptions).map(o=>o.value),f=$('#bulkFrom').value,t=$('#bulkTo').value,sh=$('#bulkShift').value;if(!f||!t||!ids.length)return alert('Completa rango/personas');range(f,t).forEach(d=>{S.schedule[d]=S.schedule[d]||{morning:[],evening:[]};S.schedule[d][sh]=Array.from(new Set([...(S.schedule[d][sh]||[]),...ids]))});$('#bulkDialog').close();render()};$('#btnReport').onclick=()=>{S.lastReport=report(S.date.getFullYear(),S.date.getMonth());$('#reportContent').innerHTML=`<table class="table"><tr><th>Persona</th><th>Mañana</th><th>Tarde</th><th>Festivo</th><th>Total</th></tr>${S.lastReport.map(r=>`<tr><td>${r.name}</td><td>${r.morningHours}</td><td>${r.eveningHours}</td><td>${r.holidayHours}</td><td>${r.totalHours}</td></tr>`).join('')}</table>`;$('#reportDialog').showModal()};$('#downloadReport').onclick=e=>{e.preventDefault();const csv=['Persona;Mañana;Tarde;Festivo;Total',...S.lastReport.map(r=>`${r.name};${r.morningHours};${r.eveningHours};${r.holidayHours};${r.totalHours}`)].join('\n');dlt('reporte-horas.csv',csv)};$('#btnExport').onclick=()=>{dl('schedule.json',S.schedule);dl('users.json',S.users);dl('holidays.json',S.holidays)};$('#btnGitHub').onclick=()=>$('#githubDialog').showModal();$('#runGitHub').onclick=e=>{e.preventDefault();alert('Usa Exportar JSON o configura guardado GitHub en la siguiente iteración. El token no se guarda.')};}
function fatal(err){console.error(err);$('.main').innerHTML=`<div style="margin:24px;padding:16px;background:#fff1f2;border:2px solid #ef3340;border-radius:10px"><h2>Error cargando la app</h2><p>${err.message||err}</p><p>Comprueba que existen css, js y data en la raíz publicada.</p></div>`}load().then(()=>{bind();render()}).catch(fatal);
})();
